/* Project Tabs & Folder Management */
.project-tabs-bar{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);margin-bottom:28px;gap:12px;padding-bottom:12px}
.project-tabs-scroll{display:flex;gap:6px;overflow-x:auto;padding-bottom:4px;flex:1}
.project-tab{display:inline-flex;align-items:center;gap:8px;padding:8px 14px;border-radius:9px;font-size:12px;color:var(--muted);border:1px solid var(--line);background:var(--surface);white-space:nowrap;transition:background .15s,color .15s}
.project-tab:hover{background:var(--hover);color:var(--text)}
.project-tab.active{background:var(--raised);color:var(--accent);border-color:#a8e6cf40}
.project-tab svg{width:15px;height:15px}
.project-tab .close-tab{width:16px;height:16px;border-radius:50%;display:grid;place-items:center;font-size:13px;line-height:1;color:var(--faint);margin-right:2px}
.project-tab .close-tab:hover{background:var(--hover);color:var(--text)}
.mini{padding:6px 11px!important;font-size:11px!important}
.projects-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:16px;margin-top:15px}
.project-card{border:1px solid var(--line);border-radius:14px;padding:20px;background:var(--surface);display:flex;flex-direction:column;gap:14px;transition:transform .15s,box-shadow .15s}
.project-card:hover{transform:translateY(-2px);box-shadow:var(--shadow)}
.project-card-top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.project-card-top h3{font-size:15px;font-weight:600;display:flex;align-items:center;gap:8px}
.project-card-top h3 svg{width:18px;height:18px;color:var(--accent)}
.project-card-path{background:var(--sidebar);border:1px solid var(--line);border-radius:8px;padding:6px 10px;font-family:Consolas,monospace;font-size:11px;color:var(--muted);direction:ltr;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.project-card-desc{font-size:12px;color:var(--muted);line-height:1.7;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.project-card-stats{display:flex;gap:16px;font-size:11px;color:var(--faint);border-top:1px solid var(--line);padding-top:12px}
.project-card-stats span{display:flex;align-items:center;gap:5px}
.project-card-stats b{color:var(--text);font-weight:500}
.project-card-actions{display:flex;gap:8px;justify-content:flex-end}
.project-header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}
.project-header-start{flex:1;min-width:0}
.project-header-start h1{font-size:26px;font-weight:600;margin:6px 0}
.project-header-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.back-link{display:inline-flex;align-items:center;gap:6px;font-size:11px;color:var(--accent);padding:0 0 8px}
.back-link:hover{text-decoration:underline}
.back-link svg{width:14px;height:14px}
.folder-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;margin-bottom:28px}
.folder-card-top{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}
.folder-info{display:flex;align-items:center;gap:12px;min-width:0;flex:1}
.folder-icon{width:36px;height:36px;border-radius:10px;background:var(--raised);display:grid;place-items:center;color:var(--accent);flex-shrink:0}
.folder-icon svg{width:20px;height:20px}
.folder-info strong{display:block;font-size:13px;font-weight:600}
.folder-info code{font-size:11px;color:var(--muted);direction:ltr;unicode-bidi:isolate;word-break:break-all}
.folder-badges{display:flex;align-items:center;gap:8px}
.folder-status-pill{display:inline-flex;align-items:center;gap:6px;font-size:10px;padding:4px 9px;border-radius:6px;background:var(--raised);color:var(--muted);border:1px solid var(--line)}
.folder-status-pill.connected{color:var(--accent);border-color:#a8e6cf30}
.folder-status-pill.error{color:var(--danger);border-color:#f3999930}
.folder-files-panel{margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}

.folder-files-list{display:flex;flex-wrap:wrap;gap:6px;max-height:160px;overflow-y:auto}
.folder-file-chip{display:inline-flex;align-items:center;gap:5px;font-size:10px;padding:4px 8px;border-radius:6px;background:var(--raised);border:1px solid var(--line);color:var(--muted);direction:ltr}
.folder-file-chip.is-dir{color:var(--accent)}
.folder-file-chip svg{width:12px;height:12px}
.project-tasks-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}
.project-tasks-header h2{font-size:18px;font-weight:600}
.project-tasks-grid{display:flex;flex-direction:column;gap:12px}
.task-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 18px;display:flex;flex-direction:column;gap:10px;transition:border-color .15s}
.task-card:hover{border-color:#ffffff25}
.task-card-top{display:flex;justify-content:space-between;align-items:center;gap:10px}
.task-card-title{font-size:14px;font-weight:600;display:flex;align-items:center;gap:8px}
.task-card-badges{display:flex;align-items:center;gap:6px}
.badge-priority{font-size:9px;padding:2px 6px;border-radius:5px;font-weight:600;direction:ltr}
.badge-priority.P0{background:#ff4d4f25;color:#ff7875;border:1px solid #ff4d4f40}
.badge-priority.P1{background:#faad1425;color:#ffc53d;border:1px solid #faad1440}
.badge-priority.P2{background:#1890ff25;color:#69c0ff;border:1px solid #1890ff40}
.badge-priority.P3{background:var(--raised);color:var(--faint);border:1px solid var(--line)}
.task-objective{font-size:12px;color:var(--muted);line-height:1.8}
.task-criteria{display:flex;flex-direction:column;gap:4px;background:var(--raised);border-radius:8px;padding:10px 12px;font-size:11px}
.task-criteria-item{display:flex;align-items:flex-start;gap:6px;color:var(--muted)}
.task-criteria-item svg{width:13px;height:13px;color:var(--accent);margin-top:2px;flex-shrink:0}
.task-card-foot{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--line);padding-top:10px;font-size:11px;color:var(--faint)}
.task-card-actions{display:flex;align-items:center;gap:6px}
.path-feedback{font-size:11px;margin-top:5px;min-height:18px}
.path-feedback.success{color:var(--accent)}
.path-feedback.error{color:var(--danger)}
.grid-2-col{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:8px}
.install-bar-btn{width:100%;border:1px solid #a8e6cf35;background:#a8e6cf10;color:var(--accent);border-radius:10px;padding:9px 12px;display:flex;align-items:center;justify-content:center;gap:8px;font-size:11px;font-weight:500;margin-bottom:12px;cursor:pointer;transition:background .15s}
.install-bar-btn:hover{background:#a8e6cf20;color:#fff}
.install-bar-btn svg{width:15px;height:15px}
.install-info-box{background:var(--surface);border-radius:12px;padding:16px;border:1px solid var(--line);margin:16px 0}
.install-info-box p{font-size:12px;margin-bottom:10px}
.install-features{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:8px;font-size:11px;color:var(--muted)}
.install-actions{display:flex;flex-direction:column;gap:12px;margin-top:20px}
.full-width{width:100%}
.installer-hint{font-size:11px;color:var(--faint);text-align:center;display:flex;flex-direction:column;gap:4px}
.installer-hint code{background:var(--raised);padding:4px 8px;border-radius:6px;color:var(--accent);direction:ltr;width:fit-content;margin:0 auto}
.project-picker-list{display:flex;flex-direction:column;gap:6px;max-height:280px;overflow-y:auto;margin-top:14px}
.project-picker-item{display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border:1px solid var(--line);border-radius:10px;background:var(--surface);cursor:pointer;text-align:right}
.project-picker-item:hover,.project-picker-item.active{background:var(--hover);border-color:var(--accent)}
.project-picker-item strong{font-size:13px;display:block}
.project-picker-item small{font-size:10px;color:var(--muted);direction:ltr;display:block}

/* Agent Drawer & Output Viewer */
.agent-card{cursor:pointer;border-radius:10px;padding:8px 10px;margin:3px 0;transition:background .15s,border-color .15s;border:1px solid transparent}
.agent-card:hover{background:var(--surface);border-color:var(--line)}
.agent-card.active{background:var(--surface);border-color:var(--accent);box-shadow:0 0 0 1px #a8e6cf40}
.agent-output-viewer{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:14px;margin:15px 0;display:flex;flex-direction:column;gap:10px;animation:fadeIn .2s ease}
@keyframes fadeIn{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}
.agent-output-header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:8px}
.agent-output-actions{display:flex;gap:4px}
.agent-output-meta{display:flex;flex-wrap:wrap;gap:8px;font-size:11px;color:var(--muted);align-items:center}
.agent-output-meta code{font-size:10px;background:var(--raised);padding:1px 5px;border-radius:4px}
.badge-done{color:var(--accent);font-weight:500}
.badge-running{color:#82b5dc;font-weight:500}
.badge-error{color:var(--danger);font-weight:500}
.agent-output-body{max-height:280px;overflow-y:auto;font-size:12px;line-height:1.8;padding-right:2px}
.check-item{cursor:pointer;transition:background .15s;padding:6px 8px;border-radius:6px}
.check-item:hover{background:var(--hover)}

