#agents-dialog{width:min(650px,calc(100vw - 24px));max-height:90vh;overflow-y:auto}#agents-dialog .dialog-shell{max-width:none}.base-agent-editor{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:12px}.base-agent-editor select{max-width:65%;min-width:0}.base-agent-editor select,.custom-agent-editor input:not([type=checkbox]),.custom-agent-editor select,.custom-agent-editor textarea{padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text);font-family:inherit;font-size:12px}.custom-agents-heading{display:flex;justify-content:space-between;align-items:center;margin-top:25px}.custom-agents-heading h3{font-size:14px}.custom-agent-editor{border:1px solid var(--line);border-radius:13px;padding:14px;margin-top:14px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.custom-agent-editor label{display:flex;flex-direction:column;gap:6px;font-size:11px;min-width:0}.custom-agent-editor label:last-child{grid-column:1/-1}.custom-editor-top{grid-column:1/-1;display:flex;justify-content:space-between}.custom-editor-top label{flex-direction:row;align-items:center}.custom-agent-editor select{width:100%;direction:ltr}#agents-error{color:#f38b8b;font-size:12px;margin-top:12px}#manage-agents{width:100%;margin-bottom:14px}button:disabled{opacity:.5;cursor:default}
@media(max-width:650px){.composer-toolbar{flex-wrap:wrap}.composer-submit{margin-inline-start:auto}select.workflow-button{max-width:130px}}

