    if(outcome === 'accepted') toast('برنامه روی سیستم شما نصب شد!');
    state.deferredPrompt = null;
  } else {
    toast('برای نصب دسکتاپ، فایل Install-Flux.bat در پوشهٔ برنامه را اجرا کنید.');
  }
