'use strict';
const $=id=>document.getElementById(id);
const state={status:null,chats:[],chat:null,cwd:'',busy:false,turn:null,after:0,events:[],polling:false,requestKey:null};
const names={codex:'Codex',claude:'Claude Code'};
const labels={queued:'در صف اجرا',running:'در حال انجام کار',completed:'پایان اجرا',failed:'خطای اجرا',cancelled:'متوقف شد',interrupted:'اجرا قطع شد',needs_input:'نیاز به بررسی شما'};
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:'اطلاعات واردشده معتبر نیست.');return data;}
const post=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)});
function showError(error){$('error').textContent=error.message||String(error);$('error').hidden=false;}
function textNode(tag,text,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;return el;}
function renderContent(el,text){
 el.replaceChildren();const pieces=text.split(/(```[^\n]*\n[\s\S]*?```)/g);
 for(const piece of pieces){if(piece.startsWith('```')&&piece.endsWith('```')){const pre=document.createElement('pre');pre.append(textNode('code',piece.replace(/^```[^\n]*\n/,'').slice(0,-3)));el.append(pre);}else el.append(document.createTextNode(piece));}
}
function active(){return state.chat?.turns?.find(t=>['queued','running'].includes(t.state));}
function models(){const items=state.status?.models?.[$('provider').value]||[];$('model-list').replaceChildren(...items.map(m=>{const o=document.createElement('option');o.value=m;return o;}));}
function lockSettings(){const locked=!!state.chat;for(const id of ['provider','model','access','folder-button'])$(id).disabled=locked;$('send').textContent=active()?'توقف اجرا':state.busy?'در حال ارسال…':'ارسال ↑';$('send').disabled=state.busy;$('prompt').required=!active();}
function history(){
 $('history').replaceChildren();for(const chat of state.chats){const b=textNode('button','',`history-item${state.chat?.id===chat.id?' selected':''}`);b.append(textNode('strong',chat.title),textNode('small',`${names[chat.provider]} · ${chat.model||'مدل پیش‌فرض'}`));b.onclick=()=>openChat(chat.id);$('history').append(b);}
}
function renderChat(){
 const turns=state.chat?.turns||[];const viewport=$('conversation');const atBottom=viewport.scrollHeight-viewport.scrollTop-viewport.clientHeight<120;
 $('welcome').hidden=turns.length>0;$('messages').replaceChildren();$('chat-title').textContent=state.chat?.title||'فضایی برای انجام کار';
 $('chat-subtitle').textContent=state.chat?`${names[state.chat.provider]} · ${state.chat.model||'مدل پیش‌فرض'} · ${state.chat.access==='read'?'فقط خواندن':'ویرایش و اجرا'}`:'با حساب‌های خودت، روی پروژه‌های خودت';
 $('folder-label').textContent=state.cwd||'پوشهٔ کاری';$('folder-button').title=state.cwd;
 for(const turn of turns){
  const user=textNode('article','', 'message user');user.append(textNode('div',turn.prompt,'message-content'));
  const assistant=textNode('article','','message assistant');assistant.append(textNode('div',names[state.chat.provider],'message-label'));
  const content=textNode('div','','message-content');renderContent(content,turn.text||(['queued','running'].includes(turn.state)?'در حال اتصال و انجام کار…':''));assistant.append(content);
  if(turn.error)assistant.append(textNode('div',turn.error,'turn-error'));
  const tokens=(turn.usage.input_tokens||0)+(turn.usage.output_tokens||0);assistant.append(textNode('div',`${labels[turn.state]||turn.state}${tokens?' · '+tokens.toLocaleString('fa-IR')+' توکن':''}`,'turn-meta'));
  const actions=textNode('div','','message-actions');
  const copy=textNode('button','کپی پاسخ');copy.onclick=()=>navigator.clipboard.writeText(turn.text).catch(showError);
  const exportButton=textNode('button','دریافت پاسخ');exportButton.onclick=()=>{const url=URL.createObjectURL(new Blob([turn.text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='flux-response.md';a.click();URL.revokeObjectURL(url);};
  const inspect=textNode('button','دیدن فعالیت');inspect.onclick=()=>loadActivity(turn.id);actions.append(copy,exportButton,inspect);assistant.append(actions);$('messages').append(user,assistant);
 }
 if(atBottom)viewport.scrollTop=viewport.scrollHeight;
 $('run-status').textContent=active()?labels[active().state]:'';lockSettings();history();
}
async function loadChats(){state.chats=await api('/api/local/chats');history();}
async function openChat(id){try{state.chat=await api('/api/local/chats/'+id);state.cwd=state.chat.cwd;$('provider').value=state.chat.provider;$('model').value=state.chat.model;$('access').value=state.chat.access;models();state.turn=state.chat.turns.at(-1)?.id;state.after=0;state.events=[];$('activity').replaceChildren();$('sidebar').classList.remove('open');renderChat();$('conversation').scrollTop=$('conversation').scrollHeight;if(state.turn)await fetchEvents(state.turn);}catch(e){showError(e);}}
function newChat(){state.chat=null;state.turn=null;state.after=0;state.events=[];state.requestKey=null;$('activity').replaceChildren();$('error').hidden=true;renderChat();$('prompt').focus();$('sidebar').classList.remove('open');}
async function fetchEvents(id){const events=await api(`/api/local/turns/${id}/events?after=${state.after}`);if(state.turn!==id)return;for(const event of events){state.after=event.sequence;state.events.push(event);if(event.kind==='tool'){const details=document.createElement('details');details.className='activity-event';const data=event.payload;details.append(textNode('summary',`${data.name} · ${data.status||''}`));details.append(textNode('pre',JSON.stringify(data,null,2)));$('activity').append(details);}}}
async function loadActivity(id){state.turn=id;state.after=0;state.events=[];$('activity').replaceChildren();$('activity-panel').hidden=false;$('activity-toggle').setAttribute('aria-expanded','true');try{await fetchEvents(id);}catch(e){showError(e);}}
async function tick(){if(state.polling)return;state.polling=true;try{if(state.chat&&active()){const id=state.chat.id;const chat=await api('/api/local/chats/'+id);if(state.chat?.id!==id)return;state.chat=chat;renderChat();const turn=chat.turns.at(-1);if(turn&&state.turn===turn.id)await fetchEvents(turn.id);if(!active())await loadChats();}}catch(e){showError(e);}finally{state.polling=false;}}
async function submit(event){
 event.preventDefault();if(state.busy)return;$('error').hidden=true;state.busy=true;lockSettings();
 try{
  const running=active();if(running){await post('/api/local/turns/'+running.id+'/cancel',{});state.chat=await api('/api/local/chats/'+state.chat.id);renderChat();return;}
  const prompt=$('prompt').value.trim();if(!prompt)return;
  if(!state.chat)state.chat=await post('/api/local/chats',{provider:$('provider').value,model:$('model').value.trim(),cwd:state.cwd,access:$('access').value});
  state.requestKey=state.requestKey||crypto.randomUUID();const turn=await post(`/api/local/chats/${state.chat.id}/turns`,{prompt,request_key:state.requestKey,use_memory:$('use-memory').checked});
  state.requestKey=null;$('prompt').value='';state.turn=turn.id;state.after=0;state.events=[];$('activity').replaceChildren();state.chat=await api('/api/local/chats/'+state.chat.id);await loadChats();renderChat();$('conversation').scrollTop=$('conversation').scrollHeight;
 }catch(e){showError(e);}finally{state.busy=false;lockSettings();}
}
async function connections(refresh=false){state.status=await api('/api/local/status'+(refresh?'?refresh=true':''));models();const providers=state.status.providers;$('connection-count').textContent=providers.filter(p=>p.authenticated).length+'/۲';$('provider-cards').replaceChildren();for(const p of providers){const card=textNode('div','','provider-card');card.append(textNode('strong',names[p.id]),textNode('small',p.version||'نصب نشده'),textNode('p',p.detail,p.authenticated?'ready':''));if(!p.authenticated){let command;if(!p.installed)command=p.id==='claude'?'winget install --id Anthropic.ClaudeCode --exact':'npm install -g @openai/codex';else command=p.id==='claude'?'claude auth login':'codex login';card.append(textNode('code',command));card.append(textNode('small','این فرمان را در ترمینال سیستم اجرا کن و ورود را در مرورگر کامل کن.'));}if(p.path)card.append(textNode('small',p.path));$('provider-cards').append(card);}}
$('composer').onsubmit=submit;$('prompt').oninput=()=>{state.requestKey=null;};$('prompt').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('composer').requestSubmit();}};
$('new-chat').onclick=newChat;$('provider').onchange=()=>{$('model').value='';models();};
$('connections-button').onclick=()=>{$('connections').showModal();connections(true).catch(showError);};$('refresh-status').onclick=async()=>{const button=$('refresh-status');button.disabled=true;try{await connections(true);}catch(e){showError(e);}finally{button.disabled=false;}};
$('folder-button').onclick=()=>{$('cwd').value=state.cwd;$('folder-error').hidden=true;$('folder-dialog').showModal();};
$('folder-form').onsubmit=e=>{e.preventDefault();const path=$('cwd').value.trim();if(!path)return;state.cwd=path;$('folder-dialog').close();renderChat();};

$('menu-button').onclick=()=>$('sidebar').classList.toggle('open');$('activity-toggle').onclick=()=>{const hidden=!$('activity-panel').hidden;$('activity-panel').hidden=hidden;$('activity-toggle').setAttribute('aria-expanded',String(!hidden));};$('close-activity').onclick=()=>{$('activity-panel').hidden=true;$('activity-toggle').setAttribute('aria-expanded','false');};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();for(const b of document.querySelectorAll('[data-prompt]'))b.onclick=()=>{$('prompt').value=b.dataset.prompt;$('prompt').focus();};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();newChat();}});
(async()=>{try{await connections();state.cwd=state.status.default_cwd;await loadChats();renderChat();if(!state.status.providers.some(p=>p.authenticated))$('connections').showModal();}catch(e){showError(e);}setInterval(tick,650);})();

def __init__(self, conn: sqlite3.Connection):
    self.conn = conn
    self._lock = threading.RLock()

def clean_text(value: str, limit: int = 20000) -> str:
    value = value.strip()
    if len(value) > limit:
        raise ValueError(f"متن باید کمتر از {limit} نویسه باشد.")
    if re.search(r"sk-[A-Za-z0-9_-]{16,}|-----BEGIN .*PRIVATE KEY-----", value):
        raise ValueError("کلید یا اطلاعات محرمانه را وارد گفت‌وگو و حافظه نکنید.")
    return value

def create_conversation(self, title):
    ident = "chat_" + uuid.uuid4().hex[:12]
    with self.repo._lock, self.conn:
        self.conn.execute("INSERT INTO conversations VALUES (?,?,?,?,0)",
                          (ident, clean_text(title, 160), now(), now()))
    return self.get_conversation(ident)

def get_conversation(self, ident):
    r = self.conn.execute("SELECT * FROM conversations WHERE id=?", (ident,)).fetchone()
    return dict(r) if r else None

def update_conversation(self, ident, title=None, archived=None):
    with self.repo._lock, self.conn:
        if title is not None:
            self.conn.execute("UPDATE conversations SET title=? WHERE id=?", (clean_text(title, 160), ident))
        if archived is not None:
            self.conn.execute("UPDATE conversations SET archived=? WHERE id=?", (int(archived), ident))
    return self.get_conversation(ident)

def save_memory(self, title, content, enabled=True, ident=None):
    title, content = clean_text(title, 120), clean_text(content, 12000)
    if not title or not content:
        raise ValueError("عنوان و متن حافظه را وارد کنید.")
    with self.repo._lock, self.conn:
        if ident:
            if not self.conn.execute("SELECT 1 FROM memories WHERE id=?", (ident,)).fetchone():
                raise KeyError(ident)
            self.conn.execute('''UPDATE memories SET title=?,content=?,enabled=?,
                revision=revision+1,updated_at=? WHERE id=?''', (title, content, int(enabled), now(), ident))
        else:
            ident = "mem_" + uuid.uuid4().hex[:12]
            self.conn.execute("INSERT INTO memories VALUES (?,?,?,?,1,?,?)",
                              (ident, title, content, int(enabled), now(), now()))
    return dict(self.conn.execute("SELECT * FROM memories WHERE id=?", (ident,)).fetchone())

def delete_memory(self, ident):
    with self.repo._lock, self.conn:
        return self.conn.execute("DELETE FROM memories WHERE id=?", (ident,)).rowcount > 0

def preferences(self):
    values = {"daily_budget": 5.0, "default_budget": 0.5, "theme": "dark"}
    values.update({r[0]: json.loads(r[1]) for r in self.conn.execute("SELECT key,value FROM preferences")})
    return values

def save_preferences(self, values):
    with self.repo._lock, self.conn:
        for key, value in values.items():
            self.conn.execute("INSERT OR REPLACE INTO preferences VALUES (?,?)", (key, json.dumps(value)))
    return self.preferences()

def accept(self, run_id):
    content = json.dumps(self.repo.get_subtasks(run_id), sort_keys=True, ensure_ascii=False)
    digest = hashlib.sha256(content.encode()).hexdigest()
    with self.repo._lock, self.conn:
        self.conn.execute("INSERT OR REPLACE INTO acceptances VALUES (?,?,?)", (run_id, digest, now()))
    return self.acceptance(run_id)

def acceptance(self, run_id):
    r = self.conn.execute("SELECT * FROM acceptances WHERE run_id=?", (run_id,)).fetchone()
    return dict(r) if r else None

def update_project(self, ident, name=None, path=None, description=None, default_criteria=None, default_budget=None, archived=None):
    project = self.get_project(ident)
    if not project:
        return None
    with self.repo._lock, self.conn:
        if name is not None:
            self.conn.execute("UPDATE projects SET name=?, updated_at=? WHERE id=?", (clean_text(name, 120), now(), ident))
        if path is not None:
            self.conn.execute("UPDATE projects SET path=?, updated_at=? WHERE id=?", (clean_text(path, 1000), now(), ident))
        if description is not None:
            self.conn.execute("UPDATE projects SET description=?, updated_at=? WHERE id=?", (clean_text(description, 5000), now(), ident))
        if default_criteria is not None:
            self.conn.execute("UPDATE projects SET default_criteria=?, updated_at=? WHERE id=?", (clean_text(default_criteria, 5000), now(), ident))
        if default_budget is not None:
            self.conn.execute("UPDATE projects SET default_budget=?, updated_at=? WHERE id=?", (float(default_budget), now(), ident))
        if archived is not None:
            self.conn.execute("UPDATE projects SET archived=?, updated_at=? WHERE id=?", (int(archived), now(), ident))
    return self.get_project(ident)

def create_project_task(self, project_id, title, objective, acceptance_criteria, budget_cap_usd=0.5, priority="P1", workflow="low"):
    if not self.get_project(project_id):
        raise ValueError("پروژه پیدا نشد.")
    ident = "ptask_" + uuid.uuid4().hex[:12]
    title = clean_text(title, 160)
    objective = clean_text(objective, 12000)
    if isinstance(acceptance_criteria, list):
        crit_json = json.dumps([clean_text(c, 1000) for c in acceptance_criteria if c.strip()], ensure_ascii=False)
    else:
        crit_json = json.dumps([clean_text(acceptance_criteria, 1000)], ensure_ascii=False)
    ts = now()
    with self.repo._lock, self.conn:
        self.conn.execute("INSERT INTO project_tasks VALUES (?,?,?,?,?,?,?,?,?,NULL,?,?)",
                          (ident, project_id, title, objective, crit_json, float(budget_cap_usd), priority, workflow, "PENDING", ts, ts))
        self.conn.execute("UPDATE projects SET updated_at=? WHERE id=?", (ts, project_id))
    return self.get_project_task(ident)

def update_project_task(self, task_id, title=None, objective=None, acceptance_criteria=None,
                        budget_cap_usd=None, priority=None, workflow=None, status=None, last_run_id=None):
    task = self.get_project_task(task_id)
    if not task:
        return None
    ts = now()
    with self.repo._lock, self.conn:
        if title is not None:
            self.conn.execute("UPDATE project_tasks SET title=?, updated_at=? WHERE id=?", (clean_text(title, 160), ts, task_id))
        if objective is not None:
            self.conn.execute("UPDATE project_tasks SET objective=?, updated_at=? WHERE id=?", (clean_text(objective, 12000), ts, task_id))
        if acceptance_criteria is not None:
            if isinstance(acceptance_criteria, list):
                crit_json = json.dumps([clean_text(c, 1000) for c in acceptance_criteria if c.strip()], ensure_ascii=False)
            else:
                crit_json = json.dumps([clean_text(acceptance_criteria, 1000)], ensure_ascii=False)
            self.conn.execute("UPDATE project_tasks SET acceptance_criteria=?, updated_at=? WHERE id=?", (crit_json, ts, task_id))
        if budget_cap_usd is not None:
            self.conn.execute("UPDATE project_tasks SET budget_cap_usd=?, updated_at=? WHERE id=?", (float(budget_cap_usd), ts, task_id))
        if priority is not None:
            self.conn.execute("UPDATE project_tasks SET priority=?, updated_at=? WHERE id=?", (priority, ts, task_id))
        if workflow is not None:
            self.conn.execute("UPDATE project_tasks SET workflow=?, updated_at=? WHERE id=?", (workflow, ts, task_id))
        if status is not None:
            self.conn.execute("UPDATE project_tasks SET status=?, updated_at=? WHERE id=?", (status, ts, task_id))
        if last_run_id is not None:
            self.conn.execute("UPDATE project_tasks SET last_run_id=?, updated_at=? WHERE id=?", (last_run_id, ts, task_id))
        self.conn.execute("UPDATE projects SET updated_at=? WHERE id=?", (ts, task["project_id"]))
    return self.get_project_task(task_id)

async def test_sol():
    # Let's inspect call to gpt-5.6-sol with a sample prompt like technical analysis
    messages = [
        {"role": "system", "content": 'You are Technical Agent (GPT-5.6 Sol).\nCRITICAL CONSTRAINTS:\n- Output ONLY valid JSON matching this Envelope schema:\n{"agent": "sol", "model_id": "gpt-5.6-sol", "subtask_id": "st2", "status": "completed", "summary": "string", "output": {"content": "string"}}\nWrite user-facing content in Persian.'},
        {"role": "user", "content": 'تحلیل فنی پروژهٔ Ageis در مسیر D:\\project\\Ageis-2-main و بررسی اشکالات.'}
    ]
    print("\n--- Testing gpt-5.6-sol with response_format=json_object ---")
    try:
        resp = await client.chat.completions.create(
            model="gpt-5.6-sol",
            messages=messages,
            max_tokens=3500,
            temperature=0.2,
            response_format={"type": "json_object"}
        )
        choice = resp.choices[0]
        print("Finish reason:", choice.finish_reason)
        print("Message content:", repr(choice.message.content))
        print("Message refusal:", getattr(choice.message, "refusal", None))
        for attr in dir(choice.message):
            if not attr.startswith("_") and attr not in ("content", "role"):
                val = getattr(choice.message, attr, None)
                if val:
                    print(f"  {attr}: {repr(val)[:150]}")
    except Exception as e:
        print("Error with response_format:", type(e), e)

    print("\n--- Testing gpt-5.6-sol WITHOUT response_format ---")
    try:
        resp2 = await client.chat.completions.create(
            model="gpt-5.6-sol",
            messages=messages,
            max_tokens=3500,
            temperature=0.2,
        )
        choice2 = resp2.choices[0]
        print("Finish reason:", choice2.finish_reason)
        print("Message content:", repr(choice2.message.content)[:200])
    except Exception as e:
        print("Error without response_format:", type(e), e)

@pytest.hookimpl(tryfirst=True)
def pytest_pyfunc_call(pyfuncitem):
    """Enable running async test functions natively without external plugins."""
    if inspect.iscoroutinefunction(pyfuncitem.obj):
        testargs = {
            arg: pyfuncitem.funcargs[arg]
            for arg in pyfuncitem._fixtureinfo.argnames
            if arg in pyfuncitem.funcargs
        }
        asyncio.run(pyfuncitem.obj(**testargs))
        return True
    return None

