def safe_print(text: str = ""):
    try:
        print(text)
    except Exception:
        try:
            enc = sys.stdout.encoding or 'utf-8'
            sys.stdout.buffer.write((text + "\n").encode(enc, errors='replace'))
            sys.stdout.buffer.flush()
        except Exception:
            pass

