def compact_output(out):
    if not isinstance(out, dict):
        return out
    compacted = dict(out)
    if "output" in compacted and isinstance(compacted["output"], dict):
        out_dict = dict(compacted["output"])
        c = out_dict.get("content", "")
        if isinstance(c, str) and len(c) > 6000:
            out_dict["content"] = c[:6000] + "\n\n... [بقیه متن برای فشرده‌سازی خلاصه شد] ..."
        compacted["output"] = out_dict
    return compacted
